import{_ as d,o as e,c as o,a2 as r}from"./chunks/framework.BU31gs4v.js";const m=JSON.parse('{"title":"附录 C 横向对比：几种 agent 记忆的设计","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/c-comparison.md","filePath":"appendix/c-comparison.md","lastUpdated":1791479463000}'),a={name:"appendix/c-comparison.md"};function n(s,t,g,l,c,i){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="附录-c-横向对比-几种-agent-记忆的设计" tabindex="-1">附录 C 横向对比：几种 agent 记忆的设计 <a class="header-anchor" href="#附录-c-横向对比-几种-agent-记忆的设计" aria-label="Permalink to &quot;附录 C 横向对比：几种 agent 记忆的设计&quot;">​</a></h1><blockquote><p>本附录把 letta-code 的 MemFS 和几种常见的 agent 记忆方案放在一起比较。对其他系统只描述其公开的、稳定的设计思路，不涉及具体版本的 API 细节；需要精确信息时请以各项目的官方文档为准。</p></blockquote><h2 id="c-1-比较维度" tabindex="-1">C.1 比较维度 <a class="header-anchor" href="#c-1-比较维度" aria-label="Permalink to &quot;C.1 比较维度&quot;">​</a></h2><p>一个记忆系统可以从下面几个问题来刻画：</p><ol><li><strong>存储介质与单位</strong>：数据库字段？向量？文件？一条“记忆”多大？</li><li><strong>谁来写</strong>：agent 自己调工具？harness 自动抽取？另一个 agent？</li><li><strong>什么时候写</strong>：对话中（hot path）？对话后（background）？</li><li><strong>怎么读</strong>：常驻上下文？按需检索？两者结合？</li><li><strong>历史与回滚</strong>：能不能看到记忆是怎么演变的？写坏了怎么办？</li><li><strong>约束</strong>：格式、大小有没有强制？</li><li><strong>多机与多 agent</strong>：怎么同步？怎么隔离？</li></ol><h2 id="c-2-四种思路" tabindex="-1">C.2 四种思路 <a class="header-anchor" href="#c-2-四种思路" aria-label="Permalink to &quot;C.2 四种思路&quot;">​</a></h2><p><strong>Letta 服务器（MemGPT 一脉）。</strong> 记忆分三层：常驻系统提示的<strong>记忆块</strong>（agent 用 <code>core_memory_*</code> 一类工具改写），可检索的<strong>归档记忆</strong>（archival，向量存储里的段落，agent 用工具插入和搜索），以及<strong>回忆记忆</strong>（recall，对话历史，可搜索）。写入主要由 agent 自己在对话中通过工具完成；Letta 后来也引入了在后台整理记忆的 sleep-time agent。letta-code 的 MemFS 可以看作这套设计的“文件化”：块变成文件、改写工具变成 shell + git，后台整理变成 worktree 里的反思子 agent。</p><p><strong>抽取式记忆服务（以 Mem0 为代表）。</strong> harness（而不是 agent）在每轮对话后用一个 LLM 从消息里<strong>抽取</strong>事实，与已有记忆做相似度比较，决定新增、更新、删除还是忽略；使用时按当前问题<strong>检索</strong>相关记忆注入上下文。记忆的单位是一条条短事实，存储在向量库（可选图结构）里。它的优势是对 agent 透明、接入简单；代价是没有“常驻层”的概念——没检索到就等于不存在——也没有人类可读、可编辑、可回滚的整体视图。</p><p><strong>通用长期存储（以 LangGraph 的 Store 为代表）。</strong> 提供一个按命名空间组织的键值存储（值是 JSON 文档，可选语义检索），把“存什么、何时存”留给应用决定；配套的工具包把记忆形成分为<strong>对话中</strong>（agent 通过工具写）和<strong>后台</strong>（另一个流程在对话后整理）两种模式，并把“程序性记忆”实现为对提示词本身的优化。它是积木而不是成品：灵活，但每个应用都要自己回答本附录 C.1 的七个问题。</p><p><strong>Claude Code 的项目记忆。</strong> 以<strong>文件</strong>为中心：项目里的 <code>CLAUDE.md</code>（以及用户级、本地级的同名文件）在会话开始时进入上下文，团队可以把它提交到代码仓库；用户或 agent 编辑这些文件就是在“改记忆”。较新的版本还有自动记忆：每个项目一个记忆目录，<code>MEMORY.md</code> 作为一行一条的索引常驻上下文，每条记忆一个带 <code>name</code>/<code>description</code> 等 frontmatter 的 Markdown 文件、按需读取——与 MemFS v2 的“根索引 + 带描述的文件 + 按需加载”几乎是同一个思路，只是没有 git 版本控制、hook 校验和后台反思这几层。（本书正是在这样一个会话里写成的，它的记忆目录就在用户主目录下的 <code>.claude/projects/&lt;项目&gt;/memory/</code>。）</p><h2 id="c-3-对照表" tabindex="-1">C.3 对照表 <a class="header-anchor" href="#c-3-对照表" aria-label="Permalink to &quot;C.3 对照表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>letta-code MemFS</th><th>Letta 服务器</th><th>抽取式（Mem0 类）</th><th>通用存储（LangGraph Store 类）</th><th>Claude Code 项目记忆</th></tr></thead><tbody><tr><td>存储</td><td>git 仓库里的 Markdown</td><td>数据库（块）+ 向量库（归档）</td><td>向量库（+ 可选图）</td><td>命名空间 KV（+ 可选向量）</td><td>Markdown 文件</td></tr><tr><td>单位</td><td>文件（可大可小）</td><td>块 / 段落</td><td>短事实</td><td>应用定义的文档</td><td>文件 / 一条记忆一个文件</td></tr><tr><td>谁写</td><td>agent（shell+git）、反思子 agent、memory worker</td><td>agent（工具）、后台 agent</td><td>harness 抽取</td><td>应用决定</td><td>用户、agent</td></tr><tr><td>何时写</td><td>对话中 + 对话后（后台）</td><td>对话中 + 后台</td><td>每轮之后</td><td>应用决定</td><td>对话中</td></tr><tr><td>怎么读</td><td>core 常驻；子目录与技能只放索引；recall 检索</td><td>块常驻；归档、recall 检索</td><td>检索注入</td><td>应用决定</td><td>常驻（<code>CLAUDE.md</code>、索引）+ 按需读文件</td></tr><tr><td>历史 / 回滚</td><td><strong>完整 git 历史</strong>，可 diff、revert</td><td>有限</td><td>记忆项有更新记录（视实现）</td><td>视实现</td><td>依赖用户自己的版本控制</td></tr><tr><td>约束</td><td>hook：frontmatter、索引链、预算、只读</td><td>块大小上限</td><td>抽取器决定</td><td>无</td><td>无强制</td></tr><tr><td>多机</td><td>git 远端，回合后 push / rebase</td><td>服务器即真相</td><td>服务即真相</td><td>存储即真相</td><td><code>CLAUDE.md</code> 随代码仓库同步</td></tr><tr><td>多 agent 隔离</td><td>路径守卫 + 内核沙箱</td><td>服务端权限</td><td>按用户 / agent id 分区</td><td>命名空间</td><td>按项目目录</td></tr></tbody></table><h2 id="c-4-memfs-的独特取舍" tabindex="-1">C.4 MemFS 的独特取舍 <a class="header-anchor" href="#c-4-memfs-的独特取舍" aria-label="Permalink to &quot;C.4 MemFS 的独特取舍&quot;">​</a></h2><p>把这些放在一起看，letta-code 的选择很鲜明：</p><ul><li><strong>把记忆当代码管。</strong> 版本控制、提交前检查、分支隔离、合并、远端同步——软件工程里管理“一群人并发修改的文本”的整套工具，原封不动地拿来管理“一群 agent 并发修改的记忆”。第 16、17 章的并发设计几乎全部建立在 git 的语义上。</li><li><strong>让 agent 用通用工具写记忆。</strong> 这给了 agent 最大的表达力（可以重组目录、建技能、存图片），也把格式正确性的负担从工具 schema 转移到了 hook 和提示词上。第 6、9、15 章里小模型的种种失误，正是这个取舍的代价；更强的模型和后台反思是它的补偿。</li><li><strong>常驻与按需由目录结构表达。</strong> 不需要额外的元数据或检索系统来决定“什么常驻”——<code>mv</code> 一下就能升级或降级一条记忆。</li><li><strong>对人透明。</strong> 记忆就是一堆 Markdown 和一段 git 历史，人可以直接读、改、审。这对一个会“自己改自己”的系统来说，可能是最重要的安全属性。</li></ul><p>没有哪种设计在所有维度上占优。如果你的 agent 只需要记住几十条用户偏好，抽取式服务可能最省事；如果你在构建一个会长期演化、需要人类审计、跨机器运行的 agent，MemFS 的这套“把记忆当代码”的思路值得认真考虑。</p>',16)])])}const p=d(a,[["render",n]]);export{m as __pageData,p as default};
